SELECT
    id,
    user_id,
    comment,
    rating,
    created_at,
    updated_at
FROM product_reviews
WHERE product_id = #{productId}

AND rating = #{rating} 

ORDER BY created_at DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT COUNT(*)
FROM product_reviews
WHERE product_id = #{productId}

AND rating = #{rating}
